Test("Sku implements value equality by hand", () =>
{
    Ok(new Sku("A", 1).Equals(new Sku("A", 1)));
    Ok(!new Sku("A", 1).Equals(new Sku("A", 2)));
    Ok(!new Sku("A", 1).Equals(new Sku("B", 1)));
