{
    Eq(new Pence(1999).ToString(), "£19.99");
    Eq(new Pence(5).ToString(), "£0.05");
    Eq(new Pence(-250).ToString(), "-£2.50");
});

Test("the record struct still compares by value", () =>
{
    Ok(new Pence(100) == new Pence(100));
    Ok(new Pence(100) != new Pence(200));
});

